inputs = ['zi', 'jckykb', 'hyk', 'cagab', 'yx']
outputs = ['zi', 'jcvievb', 'hiev', 'cvevgvevb', 'ieyef']

print("Input strings:", inputs)
print("Output strings:", outputs)

# Let's manually examine the differences
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find where they differ
        for j, (c_in, c_out) in enumerate(zip(inp, outp)):
            if c_in != c_out:
                print(f"  Position {j}: '{c_in}' -> '{c_out}'")
        # Check if one is longer
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")
    else:
        print("  No change")

